    if isinstance(val, str):
        return val.strip()
    if isinstance(val, list):
        return _format_advisory_list(val)
    if isinstance(val, dict):
        return _format_advisory_dict(val)
    return ""


def _format_advisory_list(items: list[Any]) -> str:
    formatted = [_format_advisory_value(item) for item in items if item]
    return "\n".join(f"- {item}" for item in formatted if item)


def _format_advisory_dict(d: dict[str, Any]) -> str:
    sub_parts = []
    for k, v in d.items():
        formatted = _format_advisory_value(v)
        if formatted:
            sub_parts.append(f"{k.capitalize()}:\n{formatted}")
    return "\n\n".join(sub_parts)"}
